import unittest
from candidate import fib

class TestFibFunction(unittest.TestCase):
    def test_fib_zero(self):
        self.assertEqual(fib(0), 0)

    def test_fib_one(self):
        self.assertEqual(fib(1), 1)

    def test_fib_small_numbers(self):
        self.assertEqual(fib(2), 1)
        self.assertEqual(fib(3), 2)
        self.assertEqual(fib(4), 3)

    def test_fib_medium_numbers(self):
        self.assertEqual(fib(5), 5)
        self.assertEqual(fib(10), 55)
        self.assertEqual(fib(20), 6765)

    def test_fib_returns_int(self):
        result = fib(15)
        self.assertIsInstance(result, int)

    def test_fib_recursion_error_for_negative(self):
        with self.assertRaises(RecursionError):
            fib(-1)

    def test_fib_type_error_for_none(self):
        with self.assertRaises(TypeError):
            fib(None)

    def test_fib_type_error_for_string(self):
        with self.assertRaises(TypeError):
            fib("10")

    def test_fib_type_error_for_float(self):
        with self.assertRaises(TypeError):
            fib(3.5)

    def test_fib_recursion_error_for_large_input(self):
        with self.assertRaises(RecursionError):
            fib(1000)

    def test_fib_deterministic_output(self):
        self.assertEqual(fib(7), fib(7))
        self.assertEqual(fib(8), fib(8))

if __name__ == "__main__":
    unittest.main()
